package org.omnione.did.tas.model.response.protocol.vc;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * P210 Step 2: Propose Issue VC Result.
 *
 * <p>Result of VC issuance proposal.</p>
 */
@Getter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ProposeIssueVcResult {

    /**
     * TAS Transaction ID.
     *
     * <p>Generated by SDK.</p>
     */
    private String txId;

    /**
     * Issuer Transaction ID.
     *
     * <p>Received from Issuer API response.</p>
     */
    private String externalTxId;

    /**
     * Reference ID.
     *
     * <p>Issuer-provided reference number.</p>
     */
    private String refId;
}
